"""Informe de la prueba V4; nunca declara terminado el reel completo."""
import sys,html
sys.dont_write_bytecode=True
import workflow as w

def generar(ID):
    F='proyectos/'+ID;p=w.read_json(F+'/proyecto.json');a=w.read_json(F+'/auditoria_muestra.json');resources=w.read_json(F+'/auditoria_recursos.json');play=w.read_json(F+'/reproduccion_prueba_v4.json')
    if not all(a['comprobaciones'].values()) or play.get('error_video') or not play.get('audio_detectado'):
        raise ValueError('Corregir la prueba real antes de preparar su entrega')
    scenes=[s for s in p['escenas'] if s['inicio']<10]
    p['muestra'].update(muestra_sha256=w.digest(F+'/'+p['muestra_nombre']),edicion_sha256=w.edit_digest(p),estado='revisada_por_agente_pendiente_usuario')
    w.write_json(F+'/proyecto.json',p)
    observations=[
      {'tramo':'0–6 s','hallazgo':'El hook V3 transcribe palabras aisladas; la captura de Claude anterior no demuestra lectura web.','cambio':'Titular UNA SKILL, cámara breve, Web Fetch real, b-roll de teclado y transformación de fuentes.','estado':'Reconstruido dentro de la prueba 0–10 s'},
      {'tramo':'12–16 s','hallazgo':'Fuentes representadas por logos/tarjetas con conexiones; pocas acciones internas.','cambio':'Reemplazar por lectura auténtica y transferencia progresiva de información.','estado':'Pendiente tras aprobación de prueba'},
      {'tramo':'19–22 s','hallazgo':'Rostro reducido con fondo duplicado desenfocado y guía superior poco desarrollada.','cambio':'Recorte auténtico a ancho completo y demostración sincronizada.','estado':'Pendiente tras aprobación de prueba'},
      {'tramo':'24–33 s','hallazgo':'Predominan interfaces ilustrativas, reproductor simple y circuito; faltan demostraciones específicas.','cambio':'Revisar candidatos reales de análisis y construir solo las explicaciones necesarias.','estado':'Pendiente tras aprobación de prueba'},
      {'tramo':'34–40 s','hallazgo':'Split con relleno borroso; pregunta y resultados mediante tarjetas.','cambio':'Necesidad empresarial → investigación real → sistema → resultado, sin blur.','estado':'Pendiente tras aprobación de prueba'},
      {'tramo':'41–46 s','hallazgo':'Tarjeta CLASE permanece como elemento principal durante varios segundos.','cambio':'Transformar el resultado en recurso educativo y comentario CLASE con envío.','estado':'Pendiente tras aprobación de prueba'}]
    w.write_json(F+'/auditoria_correcciones.json',{'directiva':'ASCENDIA V4.0','exportado_previo':F+'/final_ascendia_v3.mp4','sha256_previo':w.digest(F+'/final_ascendia_v3.mp4'),'muestreo_previo':'92 fotogramas cada 0.5 s, toda la duración; inspección de las seis zonas prioritarias','observaciones':observations,'limite':'Solo se ha reconstruido y exportado el prefijo de 10 s. No se afirma haber corregido las escenas restantes.'})
    lines=['# ASCENDIA V4.0 — cronología de la prueba','', 'Alcance: primeros 10 s del crudo, sin modificar la narración. El resto requiere reconstrucción después de aprobar la prueba.','', '| Entrada–salida | Narración / idea | Composición y acción | Recurso / procedencia | Sonido y transición |','|---|---|---|---|---|']
    for s in scenes:
        b=next((x for x in p['broll'] if x['inicio']==s['inicio']),None)
        resource=b['archivo']+f' · fuente desde {b["offset"]:.2f} s' if b else 'Cámara original' if s['id']=='v4_hook' else 'Componentes SVG/GSAP propios; representación conceptual'
        sound='Riser: 1.10 s → pico 2.83 s; Burn Screen 2.65–3.20 s' if s['id']=='v4_lectura' else 'Woosh 3.72 s; máscara de monitor a página' if s['id']=='v4_trabajo' else 'Woosh 8.53 s; máscara continua hacia captura real' if s['id']=='v4_contraste' else 'Continuidad por transformación; sin sonido en cada elemento'
        lines.append(f'| {s["inicio"]:.2f}–{s["fin"]:.2f} s | {s["frase"]} | {s["objetivo"]} | {resource} | {sound} |')
    lines+=['','Fuentes: Sequel Sans Bold Disp y Scholar Italic reales. Hook editorial; no transcripción automática palabra por palabra. Después, «ni un solo» / «dólar» se integra en la composición del coste. Rojo exclusivamente en FURIOSO, como provocación del discurso.','', 'Presencia: 0–1.86 s, incluyendo split 0.62–1.86 s. División 60/40 a ancho completo, una sola grabación. El zoom de énfasis dura 0.20 s; el reencuadre, 0.24 s. Sin fondo duplicado, blur ni reconstrucción AI.','', 'Componentes reutilizables: grupos por capas; ventanas temporales; reveals con máscaras; interpolación de trazados SVG; viajes por curvas; barrido de campos; reformateo de superficies; cámara con profundidad; tipografía de resultado; controlador de varias presencias y subtítulos bajo barbilla. El guion y la selección se diseñan para cada nuevo reel.','', 'En presencias posteriores con subtítulos tradicionales, el controlador reserva espacio bajo barbilla y zona segura: por defecto adapta el split a 50/50 y la barbilla a 1600 px. Ajustar al crudo y comparar fotogramas; nunca rellenar con blur.','', 'Pendientes: revisión y aprobación del usuario; escenas 10–45.95 s; comprobar datos/funciones de Agent Reach antes del final. Web Fetch Calendly no demuestra scraping de LinkedIn ni ejecución de Agent Reach. La reacción «Google está furioso» conserva el tono provocador del narrador. La cifra 60.000 del resto todavía no está verificada.']
    w.inside(F+'/cronologia.md').write_text('\n'.join(lines)+'\n')
    editorial={'revisor':'Codex, inspección de fuentes, referencias, MP4 y fotogramas consecutivos','alcance_hasta_s':10,'estado':'pendiente_aprobacion_usuario','observaciones':['Dos archivos de biblioteca reconocidos en el render real.','Split de grabación original a ancho completo, sin relleno desenfocado.','Hook de titulares integrados, sin subtítulos convencionales automáticos.','El esquema transforma perfiles en video, formato vertical y publicaciones; campos viajan y convergen; resultado se convierte en lente y captura real.','Máscaras con porcentajes consistentes: la captura final se revela continuamente.','Se descartó la captura software con franja inferior; NVIDIA conserva el área 1080×1920.','Se compensó la latencia del limitador para preservar sincronía con la voz original.'],'evidencias':[F+'/prueba_v4_fotogramas.jpg',F+'/comparacion_split_v4.jpg',F+'/comparacion.jpg',F+'/auditoria_temporal_v4.json',F+'/reproduccion_prueba_v4.json'],'pendientes':['Calidad estética y cercanía a las referencias: aprobación de Presentador.','Los subtítulos tradicionales bajo barbilla después del hook se comprobarán cuando reaparezca el presentador en el resto.','No se encontró una captura independiente llamada porque ahora; comparación realizada con los originales.','Ninguna escena 10–45.95 s se declara corregida todavía.']}
    a['edicion_sha256']=w.edit_digest(p);a['revision_editorial']=editorial;w.write_json(F+'/auditoria_muestra.json',a)
    w.write_json(F+'/auditoria.json',{'estado':'prueba_v4_revisada_pendiente_aprobacion_usuario','alcance_hasta_s':10,'manual_sha256':w.manual()['sha256'],'edicion_sha256':w.edit_digest(p),'prueba_sha256':w.digest(F+'/'+p['muestra_nombre']),'tecnica':a['comprobaciones'],'revision_editorial':editorial,'completo_renderizado':False})
    esc=html.escape
    rows=''.join(f'<tr><td>{esc(x["tramo"])}</td><td>{esc(x["hallazgo"])}</td><td>{esc(x["estado"])}</td></tr>' for x in observations)
    timeline=''.join(f'<tr><td>{s["inicio"]:.2f}–{s["fin"]:.2f}</td><td>{esc(s["frase"])}</td><td>{esc(s["objetivo"])}</td></tr>' for s in scenes)
    candidates=''.join(f'<tr><td>{esc(x["nombre_original"][:48])}</td><td>{esc(x.get("contenido_visual") or "")}</td><td>{esc(x.get("decision") or "revisado")}</td></tr>' for x in resources['candidatos'])
    image=lambda name:f'<img src="/{F}/{name}" style="width:100%">'
    content=f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>ASCENDIA V4.0 — prueba de 10 segundos</title><style>@page{{size:A4;margin:14mm}}body{{font:11px/1.5 Arial;color:#202327}}h1{{font-size:25px}}h2{{font-size:17px}}table{{border-collapse:collapse;width:100%;font-size:10px}}td,th{{border-bottom:1px solid #ddd;padding:6px;text-align:left;vertical-align:top}}.page{{break-before:page}}.box{{padding:12px;background:#f3f1eb}}code{{font-size:10px}}img{{display:block;margin:12px 0}}</style>
    <h1>ASCENDIA V4.0</h1><p>Prueba de los primeros 10 s · {w.utc()} · pendiente de aprobación de Presentador</p>
    <div class="box">MP4 real a 1080 × 1920, 30 FPS, H.264/AAC. Voz original, dos b-rolls auténticos, split 60/40 sin fondo duplicado ni blur. El reel completo no se ha renderizado.</div>
    <h2>Resultado comprobado</h2><p>300 fotogramas analizados; ninguna alternancia sospechosa. Se revisó además el borde inferior en 105 fotogramas de fondo claro para detectar también franjas grises. Presencia: 1,86 s (18,6 %), incluido split; reconocimiento de rostro en 19 de 100 muestras, hasta 1,8 s. El reproductor completó los 10 s, mostró 300 frames sin descartes y detectó audio.</p>
    <p>B-roll físico en pantalla: 4,83 s, incluyendo 1,24 s junto al presentador. Distribución editorial por bloques: presentador 18,6 %, b-roll 35,9 %, motion 45,5 %. Las entradas y salidas se solapan; no representan una suma de áreas visuales.</p>
    <p>Dos pruebas de procedencia: teclado y ratón, correlación de píxeles {a['brolls']['trabajo']['correlacion_rgb']:.3f}; Web Fetch real, {a['brolls']['claude']['correlacion_rgb']:.3f}. Voz original y mezcla alineadas: {a['audio']['correlacion_voz_original_mezcla']:.3f}. Son verificaciones técnicas, sin sustituir la revisión estética.</p>
    <h2>Antes / después del hook y las fuentes</h2>{image('comparacion.jpg')}
    <p>Las capturas salen del V3 conservado y del nuevo MP4. No son montajes usados en lugar del render.</p>
    <div class="page"></div><h2>Split comparado con la identidad</h2>{image('comparacion_split_v4.jpg')}
    <p>INTERNACIONAL alrededor de 3 s y CLASE al comienzo presentan una división limpia, rostro grande, una grabación original a ancho completo y material contextual arriba. La prueba adapta su proporción al 60/40 solicitado. Conserva la iluminación y el fondo del nuevo crudo.</p>
    <h2>Referencias examinadas</h2><p>INTERNACIONAL 2,5–3,5 s; CLASE 0–2 s; YO 0–2 s. EDIT 7–9,75 s: transición del presentador a interfaz, archivos trasladados al chat y acercamiento a la acción. CLONE 1,8–3,12 s: filas, contador y cancelación reaccionan entre sí. AGENT 12–14,75 s: métricas, reorganización de mockups y paso a documento. Se estudiaron secuencias, no solo nombres o fondos. No se copiaron sus métricas ni se afirma haber igualado todavía su nivel.</p>
    <h2>Recursos reales incorporados</h2><table><tr><th>Archivo local</th><th>Contenido y tramo de fuente</th><th>Uso en prueba</th></tr><tr><td>Claude_lectura_web.mp4<br>34,984 s · 1920×1080 · 60 FPS</td><td>Web Fetch de Calendly y páginas interiores; fuente 4,20 s. MKV remuxeado sin recompresión. Recorte excluye al presentador ajeno.</td><td>0,62–2,84 y 8,80–10,00</td></tr><tr><td>Trabajo_pantalla.mp4<br>7,845 s · 1080×1920 · 25 FPS</td><td>Persona usando teclado/ratón y varias pantallas; fuente 0,30 s. Contexto de trabajo digital.</td><td>2,84–4,25</td></tr></table>
    <p>El terminal de Calendly es un ejemplo auténtico de lectura web. No se presenta como prueba de LinkedIn o de Agent Reach. Las cuatro fuentes de 4,25–6,32 s se identifican como esquema.</p>
    <div class="page"></div><h2>Storyboard reconstruido</h2><table><tr><th>Tiempo</th><th>Narración / idea</th><th>Acción visual</th></tr>{timeline}</table>
    <h2>Control visual y tipográfico</h2><p>Sequel Sans Bold Disp y Scholar Italic cargadas desde sus TTF reales. Titulares del hook, sin transcripción automática. Sombra negra compacta 2/4/5 px, opacidad 0,85. Rojo solo en FURIOSO. Zoom de énfasis 0,20 s; reencuadre 0,24 s; transformación de página, campos que viajan por curvas, máscaras y profundidad. Se reconstruyó la transición del resultado a la captura real, corrigiendo una máscara que permanecía cerrada hasta su último frame.</p>
    {image('prueba_v4_fotogramas.jpg')}
    <p>La revisión incluye tiras de fotogramas contiguos a 30 FPS. La captura específica «porque ahora» no figura como archivo independiente; se comparó con los videos originales. Los subtítulos tradicionales bajo barbilla posteriores al hook siguen pendientes de inspección en las futuras reapariciones.</p>
    <div class="page"></div><h2>Auditoría de recursos y automatización</h2><p>Acceso real a ambas bibliotecas. Inventario: 42 carpetas, 1.876 archivos y 1.861 videos. Se preseleccionaron 85 miniaturas (20 Claude, 33 CINEMATICS y 32 Rutina-trabajar), y un agente de recursos inspeccionó secuencias de 10 candidatos. El director verificó los dos incorporados. No se afirma haber visto íntegra toda la biblioteca.</p><table><tr><th>Candidato</th><th>Contenido observado</th><th>Decisión</th></tr>{candidates}</table>
    <h2>Herramientas</h2><p>HyperFrames 0.8.147, Node 24.20 y FFmpeg 9.0.2/NVENC utilizados en el render. Captura confirmada sobre NVIDIA RTX 4050. Playwright local utilizado para revisión, reproducción y PDF; MCP 0.0.83 ya verificado. Parakeet TDT v3: se reutiliza su transcripción alineada del mismo original. Remotion 4.0.534 está disponible y probado, sin componente incorporado a estos 10 s. Codex CLI 0.162.1 verificado; la dirección y orquestación las realiza el agente. Tella excluido por instrucción del usuario. No se instalaron herramientas nuevas.</p>
    <h2>Reglas guardadas para otros reels</h2><p>Leer completo el prompt y todas sus modificaciones; verificar herramientas; inventariar las dos bibliotecas; comprender cada frase; descargar solo candidatos pertinentes; verlos; documentar selección, recursos y tramos; animar componentes con acciones conectadas; entregar primero 10 s; auditar continuidad, borde, autenticidad y audio; obtener aprobación antes del completo. Cambiar de reel requiere un storyboard y selección propios. No se reutiliza el guion de Agent Reach por defecto.</p>
    <p>Los controles bloquean renders sin selección visual comprobada, instrucciones vigentes, revisión de prueba y escenas restantes preparadas. Se ejecutaron 17 pruebas de regresión del workflow, todas correctas. Se preserva V3 para comparación y se retiraron seis clips descartados; recursos y fuentes actuales tienen una copia canónica.</p>
    <div class="page"></div><h2>Reconstrucción del resto pendiente</h2><table><tr><th>Tramo del V3</th><th>Hallazgo</th><th>Estado</th></tr>{rows}</table>
    <p>El archivo anterior se inspeccionó a lo largo de toda su duración con 92 fotogramas cada 0,5 s. Su regla de presencia ya estaba dentro de 3 s; los problemas se concentran en selección visual, tratamiento del hook, diseño del split y complejidad de las escenas. No se inventa un exceso continuo de talking head en ese exportado.</p>
    <p>Antes del final: contrastar las funciones y cifra 60.000 del resto con fuentes pertinentes. La frase «Google está furioso» es una provocación del discurso original; no se atribuye una declaración oficial. La muestra termina a los 10 s por instrucción del usuario, durante una frase que continuará en el reel.</p>
    <p>Entregables de esta etapa: MP4 de prueba, editable y componentes, broll_manifest.csv, inventario/selección, auditoría y comparaciones. Aprobación estética de la prueba y edición completa: pendientes.</p></html>'''
    w.inside(F+'/informe.html').write_text(content)
    print('Informe preparado; estado de prueba pendiente de aprobación del usuario')

if __name__=='__main__':generar(sys.argv[1])
